/// Default maximum size in bytes for a single posting block. Used when
/// creating the blockfile writer for the sparse posting list, and as the
/// default budget for splitting a dimension's posting list into blocks.
pub const SPARSE_POSTING_BLOCK_SIZE_BYTES: usize = 16 * 1024;

#[derive(Debug, Error)]
pub enum MaxScoreError {
    #[error(transparent)]
    Blockfile(#[from] Box<dyn ChromaError>),
    #[error(transparent)]
    PostingBlock(#[from] SparsePostingBlockError),
}

impl ChromaError for MaxScoreError {
    fn code(&self) -> ErrorCodes {
        match self {
            MaxScoreError::Blockfile(err) => err.code(),
            MaxScoreError::PostingBlock(_) => ErrorCodes::Internal,
        }
    }
}

/// Upper bound on the number of `(offset, weight)` entries that fit in a single
/// posting block given a byte budget. Clamped to `[1, MAX_BLOCK_ENTRIES]`.
fn max_entries_for_posting_block(block_size_bytes: usize) -> usize {
    // Each entry costs at most ~4 bytes for the bitpacked offset delta plus 2
    // bytes for the f16 weight; a 16-byte header is reserved per block. This
    // is a conservative amortized estimate — real blocks are usually smaller.
    const PER_ENTRY_BYTES: usize = 6;
    const HEADER_BYTES: usize = 16;
    let usable = block_size_bytes.saturating_sub(HEADER_BYTES);
    (usable / PER_ENTRY_BYTES).clamp(1, MAX_BLOCK_ENTRIES)
}

