/// Returned by [`MaxScoreWriter::commit`]. Owns the underlying blockfile
/// flusher and exposes the posting id and the flush operation.
pub struct MaxScoreFlusher {
    flusher: BlockfileFlusher,
}

impl MaxScoreFlusher {
    /// Id of the committed posting blockfile.
    pub fn id(&self) -> Uuid {
        self.flusher.id()
    }

    /// Persist the committed blocks.
    pub async fn flush(self) -> Result<(), MaxScoreError> {
        self.flusher.flush::<u32, SparsePostingBlock>().await?;
        Ok(())
    }
}

