    /// Maximum bytes per posting block, used to split large posting lists.
    block_size: usize,
    /// Pending mutations, held until commit: `dim -> offset -> Some(weight)`
    /// for an upsert or `None` for a delete.
    delta: Arc<DashMap<u32, DashMap<u32, Option<f32>>>>,
    posting_writer: BlockfileWriter,
    old_reader: Option<MaxScoreReader<'me>>,
