        id: Uuid,
    ) -> MaxScoreReader<'static> {
        let br = provider
            .read::<u32, SparsePostingBlock>(BlockfileReaderOptions::new(id, "".to_string()))
            .await
            .unwrap();
        MaxScoreReader::new(br)
    }

    fn exhaustive(
        vectors: &[(u32, Vec<(u32, f32)>)],
        query: &[(u32, f32)],
        k: usize,
    ) -> Vec<(u32, f32)> {
        let mut scored: Vec<(u32, f32)> = vectors
            .iter()
            .map(|(off, v)| {
                let s: f32 = query
                    .iter()
                    .map(|(qd, qw)| {
                        v.iter()
                            .find(|(d, _)| d == qd)
                            .map(|(_, w)| w * qw)
                            .unwrap_or(0.0)
                    })
                    .sum();
                (*off, s)
            })
            .filter(|(_, s)| *s > 0.0)
            .collect();
        scored.sort_by(|a, b| b.1.total_cmp(&a.1).then(a.0.cmp(&b.0)));
        scored.truncate(k);
        scored
    }

    #[tokio::test]
    async fn query_correctness_and_dims() {
        let (_t, provider) = test_arrow_blockfile_provider(8 * 1024 * 1024);
        std::mem::forget(_t);
        let vectors = vec![
            (0u32, vec![(0u32, 1.0f32), (1, 1.0), (2, 0.5)]),
            (1, vec![(0, 0.5), (3, 1.0)]),
            (2, vec![(1, 0.5), (2, 1.0), (3, 0.5)]),
            (3, vec![(0, 0.8), (1, 0.8)]),
            (4, vec![(4, 1.0), (5, 1.0)]),
        ];
        let w = MaxScoreWriter::new(make_writer(&provider).await, None);
        for (off, v) in &vectors {
            w.set(*off, v.clone()).await;
        }
        let f = Box::pin(w.commit()).await.unwrap();
        let id = f.id();
        Box::pin(f.flush()).await.unwrap();
        let reader = make_reader(&provider, id).await;

        let mut dims = reader.get_all_dimension_ids().await.unwrap();
        dims.sort();
        assert_eq!(dims, vec![0, 1, 2, 3, 4, 5]);

        let query = vec![(0, 1.0), (1, 1.0)];
        let res = reader
            .query(query.clone(), 3, SignedRoaringBitmap::full())
            .await
            .unwrap();
        let exp = exhaustive(&vectors, &query, 3);
        assert_eq!(res.len(), 3);
        for (r, e) in res.iter().zip(exp.iter()) {
            assert_eq!(r.offset, e.0, "offset mismatch: {:?} vs {:?}", res, exp);
            assert!((r.score - e.1).abs() < 5e-3);
        }

        // k == 0
        assert!(reader
            .query(query.clone(), 0, SignedRoaringBitmap::full())
            .await
            .unwrap()
            .is_empty());
        // no matching dims
        assert!(reader
            .query(vec![(99, 1.0)], 5, SignedRoaringBitmap::full())
            .await
            .unwrap()
            .is_empty());

        // Include mask restricts to offsets present
        let mut rbm = RoaringBitmap::new();
        rbm.insert(3);
        let res = reader
            .query(vec![(0, 1.0), (1, 1.0)], 5, SignedRoaringBitmap::Include(rbm))
            .await
            .unwrap();
        assert_eq!(res.len(), 1);
        assert_eq!(res[0].offset, 3);

        // Exclude mask omits offsets present
        let mut rbm = RoaringBitmap::new();
        rbm.insert(0);
        let res = reader
            .query(vec![(0, 1.0), (1, 1.0)], 5, SignedRoaringBitmap::Exclude(rbm))
            .await
            .unwrap();
        assert!(res.iter().all(|r| r.offset != 0));
    }

    #[tokio::test]
    async fn multiblock_directory_and_large_recall() {
        let (_t, provider) = test_arrow_blockfile_provider(8 * 1024 * 1024);
        std::mem::forget(_t);
        // Many docs on a few dims; small block size to force splitting.
        let mut vectors: Vec<(u32, Vec<(u32, f32)>)> = Vec::new();
        for i in 0..400u32 {
            let dims: Vec<(u32, f32)> = ((i % 10)..(i % 10 + 5))
                .map(|d| (d, 0.01 + (i as f32) * 0.001))
                .collect();
            vectors.push((i, dims));
        }
        let w = MaxScoreWriter::new(make_writer(&provider).await, None).with_block_size(256);
        for (off, v) in &vectors {
            w.set(*off, v.clone()).await;
        }
        let f = Box::pin(w.commit()).await.unwrap();
        let id = f.id();
        Box::pin(f.flush()).await.unwrap();
        let reader = make_reader(&provider, id).await;

        // dimension 0 should have multiple blocks -> directory present
        let enc0 = encode_u32(0);
        let blocks = reader.get_posting_blocks(&enc0).await.unwrap();
        assert!(blocks.len() > 1, "expected multiblock, got {}", blocks.len());
        for b in &blocks {
            assert!(!b.is_directory());
        }
        let dir = reader.get_directory(&enc0).await.unwrap();
        let (directory, parts) = dir.expect("directory should exist");
        assert_eq!(directory.num_blocks(), blocks.len());
        assert!(parts >= 1);
        assert_eq!(directory.max_offsets().len(), blocks.len());
        assert_eq!(directory.max_weights().len(), blocks.len());

        // single-entry dimension -> no directory (dim 14 only appears rarely)
        // dims 0..14 exist; pick one that occurs once
        let query = vec![(0, 1.0), (1, 1.0), (2, 1.0)];
        let res = reader
            .query(query.clone(), 10, SignedRoaringBitmap::full())
            .await
            .unwrap();
        let exp = exhaustive(&vectors, &query, 10);
        assert_eq!(res.len(), exp.len());
        let res_set: std::collections::HashSet<u32> = res.iter().map(|r| r.offset).collect();
        let exp_set: std::collections::HashSet<u32> = exp.iter().map(|e| e.0).collect();
        // perfect recall (boundary ties within tolerance acceptable, but here scores distinct)
        assert_eq!(res_set, exp_set, "recall mismatch");
    }

